package stringalgo;
public class RabinKarp { public static int search(String text,String pattern){if(pattern.isEmpty())return 0;if(pattern.length()>text.length())return -1;long base=256,mod=1_000_000_007L,hp=0,ht=0,pow=1;for(int i=0;i<pattern.length();i++){hp=(hp*base+Character.toLowerCase(pattern.charAt(i)))%mod;ht=(ht*base+Character.toLowerCase(text.charAt(i)))%mod;if(i<pattern.length()-1)pow=pow*base%mod;}for(int i=0;i<=text.length()-pattern.length();i++){if(hp==ht&&text.regionMatches(true,i,pattern,0,pattern.length()))return i;if(i<text.length()-pattern.length()){ht=(ht-Character.toLowerCase(text.charAt(i))*pow%mod+mod)%mod;ht=(ht*base+Character.toLowerCase(text.charAt(i+pattern.length())))%mod;}}return -1;} }
